/* AIVIC_FUNCTION_BUNDLE_START owner=formatAndDisplayUnifiedReports exports=formatAndDisplayUnifiedReports */
const __aivicBundle_23_formatAndDisplayUnifiedReports = (() => {
  function formatAndDisplayUnifiedReports(
    duplicate_report_input: Array<{
      employee_id?: string;
      employee_name?: string;
      department_id?: string;
      department_name?: string;
      yesterday_achievement?: string;
      today_plan?: string;
      issues?: string;
      submitted_at?: Date;
      [key: string]: any;
    }>,
  ): {
    total_unique_reports: number;
    reports_by_employee: Array<{
      employee_id: string;
      employee_name: string;
      department_id: string;
      department_name: string;
      report_count: number;
      reports: Array<{
        yesterday_achievement: string;
        today_plan: string;
        issues: string;
        submitted_at: Date;
      }>;
    }>;
  } {
    const employeeMap = new Map<
      string,
      {
        employee_id: string;
        employee_name: string;
        department_id: string;
        department_name: string;
        reports: Array<{
          yesterday_achievement: string;
          today_plan: string;
          issues: string;
          submitted_at: Date;
        }>;
      }
    >();
  
    const uniqueReports = new Set<string>();
  
    for (const report of duplicate_report_input) {
      const employeeId = report.employee_id ?? '';
      const reportKey = JSON.stringify({
        employee_id: employeeId,
        yesterday_achievement: report.yesterday_achievement ?? '',
        today_plan: report.today_plan ?? '',
        issues: report.issues ?? '',
        submitted_at: report.submitted_at?.toISOString() ?? '',
      });
  
      if (!uniqueReports.has(reportKey)) {
        uniqueReports.add(reportKey);
  
        if (!employeeMap.has(employeeId)) {
          employeeMap.set(employeeId, {
            employee_id: employeeId,
            employee_name: report.employee_name ?? '',
            department_id: report.department_id ?? '',
            department_name: report.department_name ?? '',
            reports: [],
          });
        }
  
        const employeeData = employeeMap.get(employeeId)!;
        employeeData.reports.push({
          yesterday_achievement: report.yesterday_achievement ?? '',
          today_plan: report.today_plan ?? '',
          issues: report.issues ?? '',
          submitted_at: report.submitted_at ?? new Date(),
        });
      }
    }
  
    const reports_by_employee = Array.from(employeeMap.values()).map((emp) => ({
      employee_id: emp.employee_id,
      employee_name: emp.employee_name,
      department_id: emp.department_id,
      department_name: emp.department_name,
      report_count: emp.reports.length,
      reports: emp.reports,
    }));
  
    return {
      total_unique_reports: uniqueReports.size,
      reports_by_employee,
    };
  }
  return { formatAndDisplayUnifiedReports };
})();
export const formatAndDisplayUnifiedReports = __aivicBundle_23_formatAndDisplayUnifiedReports.formatAndDisplayUnifiedReports;
/* AIVIC_FUNCTION_BUNDLE_END owner=formatAndDisplayUnifiedReports */

