const __aivicBundle_24_sendConfirmationEmailsToBothRecipients = (() => {
  function sendConfirmationEmailsToBothRecipients(report_data: {
    employee_id?: string;
    department_head_id?: string;
    manager_user_id?: number;
    reporter_user_id?: number;
    report_content?: {
      yesterday_accomplishment?: string;
      today_plan?: string;
      current_challenge?: string;
      yesterday_achievement?: string;
      todays_plan?: string;
      issues_held?: string;
    };
    submission_timestamp?: Date;
    send_timestamp?: Date;
    report_date?: string;
    [key: string]: any;
  }): {
    employee_id: string;
    report_content: {
      yesterday_accomplishment: string;
      today_plan: string;
      current_challenge: string;
    };
    submission_timestamp: Date;
    report_date: string;
    emails_sent: number;
    email_delivery_status: string;
  } {
    // Validate manager_user_id if present
    if (report_data.manager_user_id !== undefined && report_data.manager_user_id === 0) {
      throw new Error('部長ユーザーIDが無効です');
    }
  
    // Normalize report content field names
    const normalizedContent = {
      yesterday_accomplishment:
        report_data.report_content?.yesterday_accomplishment ||
        report_data.report_content?.yesterday_achievement ||
        '',
      today_plan:
        report_data.report_content?.today_plan ||
        report_data.report_content?.todays_plan ||
        '',
      current_challenge:
        report_data.report_content?.current_challenge ||
        report_data.report_content?.issues_held ||
        '',
    };
  
    // Determine submission timestamp
    const submissionTime = report_data.submission_timestamp || report_data.send_timestamp || new Date();
  
    // Determine employee ID
    const employeeId = report_data.employee_id || String(report_data.reporter_user_id) || '';
  
    // Determine report date
    const reportDate = report_data.report_date || submissionTime.toISOString().split('T')[0];
  
    // Simulate sending confirmation emails to both employee and department head
    // In a real implementation, this would call an email service API
    // For each recipient (employee + department head), send one email
    const emailsSent = 2;
  
    return {
      employee_id: employeeId,
      report_content: normalizedContent,
      submission_timestamp: submissionTime,
      report_date: reportDate,
      emails_sent: emailsSent,
      email_delivery_status: 'success',
    };
  }
  return { sendConfirmationEmailsToBothRecipients };
})();
