/* AIVIC_FUNCTION_BUNDLE_START owner=judgeReportDelay exports=judgeReportDelay */
const __aivicBundle_28_judgeReportDelay = (() => {
  function judgeReportDelay(input: {
    submission_timestamp?: string | Date;
    scheduled_start_time?: string | Date;
    report_send_time?: string | Date;
    morning_meeting_start_time?: string | Date;
  }): { is_delayed: boolean; delayMinutes?: number; status: string } {
    // 送信時刻を決定（report_send_time または submission_timestamp）
    const sendTimeInput = input.report_send_time ?? input.submission_timestamp;
    
    // 朝会開始時刻を決定（morning_meeting_start_time または scheduled_start_time）
    const meetingTimeInput = input.morning_meeting_start_time ?? input.scheduled_start_time;
  
    // 朝会開始時刻が未定義の場合は例外をスロー
    if (meetingTimeInput === undefined) {
      throw new Error('朝会開始予定時刻が指定されていません');
    }
  
    // 送信時刻が未定義の場合は例外をスロー
    if (sendTimeInput === undefined) {
      throw new Error('報告送信時刻が指定されていません');
    }
  
    // Date オブジェクトに変換
    const sendTime = new Date(sendTimeInput);
    const meetingTime = new Date(meetingTimeInput);
  
    // 送信時刻が朝会開始時刻以前なら遅延なし
    if (sendTime <= meetingTime) {
      return {
        is_delayed: false,
        status: '定時送信',
      };
    }
  
    // 送信時刻が朝会開始時刻より後なら遅延あり
    const delayMs = sendTime.getTime() - meetingTime.getTime();
    const delayMinutes = Math.floor(delayMs / (1000 * 60));
  
    return {
      is_delayed: true,
      delayMinutes: delayMinutes,
      status: '遅延送信',
    };
  }
  return { judgeReportDelay };
})();
export const judgeReportDelay = __aivicBundle_28_judgeReportDelay.judgeReportDelay;
/* AIVIC_FUNCTION_BUNDLE_END owner=judgeReportDelay */

