/* AIVIC_FUNCTION_BUNDLE_START owner=determineSubmissionDelay exports=determineSubmissionDelay */
const __aivicBundle_43_determineSubmissionDelay = (() => {
  function determineSubmissionDelay(params: {
    meeting_start_time_ms: number;
    submission_time_ms: number;
  }): {
    is_delayed: boolean;
    delay_milliseconds: number;
    delay_category: string;
  } {
    const { meeting_start_time_ms, submission_time_ms } = params;
  
    const delay_milliseconds = submission_time_ms - meeting_start_time_ms;
    const is_delayed = delay_milliseconds > 0;
  
    let delay_category: string;
    if (delay_milliseconds <= 0) {
      delay_category = '定時';
    } else if (delay_milliseconds === 1) {
      delay_category = '1ミリ秒超過';
    } else if (delay_milliseconds < 60000) {
      delay_category = `${delay_milliseconds}ミリ秒超過`;
    } else if (delay_milliseconds < 3600000) {
      const delaySeconds = Math.floor(delay_milliseconds / 1000);
      delay_category = `${delaySeconds}秒超過`;
    } else {
      const delayMinutes = Math.floor(delay_milliseconds / 60000);
      delay_category = `${delayMinutes}分超過`;
    }
  
    return {
      is_delayed,
      delay_milliseconds: Math.max(0, delay_milliseconds),
      delay_category,
    };
  }
  return { determineSubmissionDelay };
})();
export const determineSubmissionDelay = __aivicBundle_43_determineSubmissionDelay.determineSubmissionDelay;
/* AIVIC_FUNCTION_BUNDLE_END owner=determineSubmissionDelay */

/* AIVIC_FUNCTION_BUNDLE_START owner=validateReportSubmissionTime exports=validateReportSubmissionTime */
const __aivicBundle_44_validateReportSubmissionTime = (() => {
  function validateReportSubmissionTime(params: {
    userId: string;
    currentTimeJst: Date;
    timezoneId: string;
  }): {
    isSubmissionTarget: boolean;
    targetDate: string;
    utcTime: string;
    jstTime: string;
    monthBoundaryHandled: boolean;
  } {
    if (params["timezoneId"] === undefined || params["timezoneId"] === null) { throw new Error("timezoneId is required"); }
    const { userId, currentTimeJst } = params;
  
    // JST時刻を ISO 8601 形式で取得
    
    
    // JST時刻の日付部分を抽出（YYYY-MM-DD）
    const jstDate = new Date(currentTimeJst);
    const year = jstDate.getFullYear();
    const month = String(jstDate.getMonth() + 1).padStart(2, '0');
    const day = String(jstDate.getDate()).padStart(2, '0');
    const targetDate = `${year}-${month}-${day}`;
  
    // UTC時刻を計算（JST = UTC + 9時間）
    const utcDate = new Date(currentTimeJst.getTime() - 9 * 60 * 60 * 1000);
    const utcTime = utcDate.toISOString();
  
    // JST時刻を +09:00 形式で表現
    const jstHours = String(jstDate.getHours()).padStart(2, '0');
    const jstMinutes = String(jstDate.getMinutes()).padStart(2, '0');
    const jstSeconds = String(jstDate.getSeconds()).padStart(2, '0');
    const jstTime = `${targetDate}T${jstHours}:${jstMinutes}:${jstSeconds}+09:00`;
  
    // 月境界処理の判定：UTC日付とJST日付が異なる場合、月境界をまたいでいる
    const utcYear = utcDate.getFullYear();
    const utcMonth = String(utcDate.getMonth() + 1).padStart(2, '0');
    const utcDay = String(utcDate.getDate()).padStart(2, '0');
    const utcDateStr = `${utcYear}-${utcMonth}-${utcDay}`;
    
    const monthBoundaryHandled = targetDate !== utcDateStr;
  
    // 送信対象判定：userId が存在し、有効な時刻が与えられている場合は true
    const isSubmissionTarget = userId.length > 0 && currentTimeJst instanceof Date && !isNaN(currentTimeJst.getTime());
  
    return {
      isSubmissionTarget,
      targetDate,
      utcTime,
      jstTime,
      monthBoundaryHandled,
    };
  }
  return { validateReportSubmissionTime };
})();
export const validateReportSubmissionTime = __aivicBundle_44_validateReportSubmissionTime.validateReportSubmissionTime;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateReportSubmissionTime */

