/* AIVIC_FUNCTION_BUNDLE_END owner=sendConfirmationEmailsOnReporting */

/* AIVIC_FUNCTION_BUNDLE_START owner=validateSenderEmailFormat exports=validateSenderEmailFormat */
const __aivicBundle_46_validateSenderEmailFormat = (() => {
  function validateSenderEmailFormat(emailAddress: string): { isValid: boolean; error?: string } {
    // Handle empty or non-string input
    if (!emailAddress || typeof emailAddress !== 'string') {
      return {
        isValid: false,
        error: 'Invalid email format: email address is required',
      };
    }
  
    const trimmedEmail = emailAddress.trim();
  
    // Check for empty string after trimming
    if (trimmedEmail.length === 0) {
      return {
        isValid: false,
        error: 'Invalid email format: email address cannot be empty',
      };
    }
  
    // Count @ symbols - must be exactly 1
    const atCount = trimmedEmail.split('@').length - 1;
    if (atCount !== 1) {
      return {
        isValid: false,
        error: 'Invalid email format: email must contain exactly one @ symbol',
      };
    }
  
    const [localPart, domain] = trimmedEmail.split('@');
  
    // Validate local part (before @)
    if (!localPart || localPart.length === 0) {
      return {
        isValid: false,
        error: 'Invalid email format: local part cannot be empty',
      };
    }
  
    // Check for spaces in local part
    if (localPart.includes(' ')) {
      return {
        isValid: false,
        error: 'Invalid email format: local part cannot contain spaces',
      };
    }
  
    // Validate domain part (after @)
    if (!domain || domain.length === 0) {
      return {
        isValid: false,
        error: 'Invalid email format: domain cannot be empty',
      };
    }
  
    // Domain must contain at least one dot
    if (!domain.includes('.')) {
      return {
        isValid: false,
        error: 'Invalid email format: domain must contain a dot',
      };
    }
  
    // Check for consecutive dots
    if (domain.includes('..') || localPart.includes('..')) {
      return {
        isValid: false,
        error: 'Invalid email format: consecutive dots are not allowed',
      };
    }
  
    // Check for leading or trailing dots in domain
    if (domain.startsWith('.') || domain.endsWith('.')) {
      return {
        isValid: false,
        error: 'Invalid email format: domain cannot start or end with a dot',
      };
    }
  
    // Check for spaces in domain
    if (domain.includes(' ')) {
      return {
        isValid: false,
        error: 'Invalid email format: domain cannot contain spaces',
      };
    }
  
    // Basic validation passed
    return {
      isValid: true,
    };
  }
  return { validateSenderEmailFormat };
})();
export const validateSenderEmailFormat = __aivicBundle_46_validateSenderEmailFormat.validateSenderEmailFormat;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateSenderEmailFormat */

