/* AIVIC_FUNCTION_BUNDLE_START owner=sendConfirmationEmailsToManagerAndSender exports=sendConfirmationEmailsToManagerAndSender */
const __aivicBundle_50_sendConfirmationEmailsToManagerAndSender = (() => {
  async function sendConfirmationEmailsToManagerAndSender(input: {
    submitted_members?: any[];
    manager_user?: {
      user_id: string;
      user_name: string;
      email_address: string;
      department_id: string;
      role: string;
    };
    morning_meeting_time?: Date;
    email_service?: {
      send: (params: any) => Promise<any>;
    };
    reports?: any[];
    employees?: any[];
    managerEmail?: string;
    managerId?: string;
    reportSubmissionDate?: Date;
    maxDisplayableCount?: number;
  }): Promise<{ emails_sent: number; status: string; reason?: string }> {
    const { submitted_members = [], manager_user, email_service } = input;
  
    // Early return if no submitted members
    if (!submitted_members || submitted_members.length === 0) {
      return {
        emails_sent: 0,
        status: 'early_return',
        reason: 'no_submitted_members',
      };
    }
  
    // If email service is not available, cannot send emails
    if (!email_service || !email_service.send) {
      return {
        emails_sent: 0,
        status: 'failed',
        reason: 'email_service_unavailable',
      };
    }
  
    // If manager user is not available, cannot send to manager
    if (!manager_user || !manager_user.email_address) {
      return {
        emails_sent: 0,
        status: 'failed',
        reason: 'manager_user_unavailable',
      };
    }
  
    let emailsSent = 0;
  
    // Build confirmation email content
    const reportSummary = submitted_members
      .map(
        (member: any) =>
          `${member.user_name || member.employeeName || 'Unknown'}: ${member.yesterday_achievement || member.yesterdayAchievement || ''}`
      )
      .join('\n');
  
    const managerEmailPayload = {
      recipient_email: manager_user.email_address,
      subject: 'Daily Report Submission Confirmation',
      body: `Manager notification: ${submitted_members.length} report(s) submitted.\n\n${reportSummary}`,
      report_count: submitted_members.length,
      submitted_at: new Date().toISOString(),
    };
  
    try {
      await email_service.send(managerEmailPayload);
      emailsSent += 1;
    } catch {
      // Email send failed, but continue
    }
  
    // Send confirmation to each submitted member (sender)
    for (const member of submitted_members) {
      const senderEmail = member.email_address || member.reporterEmail;
      if (!senderEmail) {
        continue;
      }
  
      const senderEmailPayload = {
        recipient_email: senderEmail,
        subject: 'Your Daily Report Submission Confirmed',
        body: `Your report has been successfully submitted on ${new Date().toISOString()}`,
        submitted_at: new Date().toISOString(),
      };
  
      try {
        await email_service.send(senderEmailPayload);
        emailsSent += 1;
      } catch {
        // Email send failed, but continue
      }
    }
  
    return {
      emails_sent: emailsSent,
      status: emailsSent > 0 ? 'success' : 'failed',
    };
  }
  return { sendConfirmationEmailsToManagerAndSender };
})();
export const sendConfirmationEmailsToManagerAndSender = __aivicBundle_50_sendConfirmationEmailsToManagerAndSender.sendConfirmationEmailsToManagerAndSender;
/* AIVIC_FUNCTION_BUNDLE_END owner=sendConfirmationEmailsToManagerAndSender */

