/* AIVIC_FUNCTION_BUNDLE_START owner=assignPromptionPriority exports=assignPromptionPriority */
const __aivicBundle_64_assignPromptionPriority = (() => {
  function assignPromptionPriority(input: {
    nonSubmittedMembers: Array<{ memberId: string; memberName: string }>;
    delayedMembers: Array<{
      memberId: string;
      memberName: string;
      submittedAt: Date;
      scheduledAt: Date;
    }>;
  }): Array<{
    memberId: string;
    memberName: string;
    delayMinutes: number;
    priority: number;
    priorityReason: string;
  }> {
    if (input["nonSubmittedMembers"] === undefined || input["nonSubmittedMembers"] === null) { throw new Error("nonSubmittedMembers is required"); }
    const results: Array<{
      memberId: string;
      memberName: string;
      delayMinutes: number;
      priority: number;
      priorityReason: string;
    }> = [];
  
    // Process delayed members with delay calculation
    const delayedWithMinutes = input.delayedMembers.map((member) => {
      const delayMs =
        member.submittedAt.getTime() - member.scheduledAt.getTime();
      const delayMinutes = Math.floor(delayMs / (1000 * 60));
      return {
        memberId: member.memberId,
        memberName: member.memberName,
        delayMinutes: Math.max(0, delayMinutes),
      };
    });
  
    // Sort delayed members by delayMinutes descending (longest delay first)
    delayedWithMinutes.sort((a, b) => b.delayMinutes - a.delayMinutes);
  
    // Assign priority to delayed members starting from 1
    delayedWithMinutes.forEach((member, index) => {
      results.push({
        memberId: member.memberId,
        memberName: member.memberName,
        delayMinutes: member.delayMinutes,
        priority: index + 1,
        priorityReason: 'delayed',
      });
    });
  
    return results;
  }
  return { assignPromptionPriority };
})();
