const __aivicBundle_95_determinePushLoopTermination = (() => {
  function determinePushLoopTermination(input: {
    push_target_member_id: string | null;
    push_attempt_count: number;
    max_push_attempts: number;
    last_push_sent_at: Date;
    push_interval_minutes: number;
  }): PromptLoopState {
    if (input.push_target_member_id === null || input.push_target_member_id === undefined) {
      throw new Error("催促対象部員IDが指定されていません");
    }
  
    const currentTime = new Date();
    const elapsedMinutes = Math.floor(
      (currentTime.getTime() - input.last_push_sent_at.getTime()) / (1000 * 60)
    );
  
    const isTimeoutExceeded = elapsedMinutes > input.push_interval_minutes;
    const isMaxAttemptsReached = input.push_attempt_count >= input.max_push_attempts;
  
    let shouldContinue = true;
    let recommendedAction: "continue" | "stop" | "notifyManager" = "continue";
  
    if (isMaxAttemptsReached) {
      shouldContinue = false;
      recommendedAction = "stop";
    } else if (isTimeoutExceeded) {
      shouldContinue = false;
      recommendedAction = "notifyManager";
    }
  
    return {
      shouldContinue,
      isTimeoutExceeded,
      isMaxAttemptsReached,
      recommendedAction,
      elapsedMinutes,
      minutesUntilMeeting: 0,
    };
  }
  return { determinePushLoopTermination };
})();
export const determinePushLoopTermination = __aivicBundle_95_determinePushLoopTermination.determinePushLoopTermination;
/* AIVIC_FUNCTION_BUNDLE_END owner=determinePushLoopTermination */

/* AIVIC_FUNCTION_BUNDLE_START owner=determinePromptionLoopEnd exports=determinePromptionLoopEnd */
const __aivicBundle_96_determinePromptionLoopEnd = (() => {
  function determinePromptionLoopEnd(
    arg1: string | { prompt_target_user_id?: string; prompt_round_number?: number; max_prompt_attempts?: number; last_report_received_at?: Date | null; prompt_deadline?: Date } | Date,
    arg2?: number,
    arg3?: number,
    arg4?: Date
  ): PromptLoopState {
    // 引数形式の判定と正規化
    let targetEmployeeId: string;
    let maxRetryCount: number;
    let currentRetryCount: number;
    let lastPromptionTimestamp: Date;
  
    if (typeof arg1 === 'string') {
      // 4引数形式: (string, number, number, Date)
      targetEmployeeId = arg1;
      maxRetryCount = arg2 ?? 0;
      currentRetryCount = arg3 ?? 0;
      lastPromptionTimestamp = arg4 ?? new Date();
    } else if (typeof arg1 === 'object' && arg1 !== null && !('toISOString' in arg1)) {
      // object形式: ({ prompt_target_user_id, ..., prompt_deadline })
      const obj = arg1 as any;
      targetEmployeeId = obj.prompt_target_user_id ?? '';
      maxRetryCount = obj.max_prompt_attempts ?? 0;
      currentRetryCount = obj.prompt_round_number ?? 0;
      lastPromptionTimestamp = obj.last_report_received_at ?? null;
      // prompt_deadline は朝会時刻として使用
      arg4 = obj.prompt_deadline;
    } else {
      // Date形式の場合は第1引数を朝会時刻として扱う
      targetEmployeeId = '';
      maxRetryCount = arg2 ?? 0;
      currentRetryCount = arg3 ?? 0;
      lastPromptionTimestamp = arg1 as Date;
    }
  
    // バリデーション
    if (!targetEmployeeId || targetEmployeeId.trim() === '') {
      throw new Error('催促対象部員IDが空文字列です');
    }
  
    if (lastPromptionTimestamp === null || lastPromptionTimestamp === undefined) {
      throw new Error('最後の再報告受信時刻が指定されていません');
    }
  
    const meetingTime = arg4 ?? new Date();
    const now = new Date();
  
    // 経過時間を計算
    const elapsedMinutes = Math.floor(
      (now.getTime() - lastPromptionTimestamp.getTime()) / (1000 * 60)
    );
  
    // 朝会までの残り時間を計算
    const minutesUntilMeeting = Math.floor(
      (meetingTime.getTime() - now.getTime()) / (1000 * 60)
    );
  
    // タイムアウト判定（経過時間がタイムアウト時間を超えたか）
    const isTimeoutExceeded = elapsedMinutes >= 20; // デフォルトタイムアウト20分
  
    // 最大試行回数判定
    const isMaxAttemptsReached = currentRetryCount >= maxRetryCount;
  
    // 継続判定
    const shouldContinue = !isTimeoutExceeded && !isMaxAttemptsReached && minutesUntilMeeting > 0;
  
    // 推奨アクション判定
    let recommendedAction: 'continue' | 'stop' | 'notifyManager';
    if (isMaxAttemptsReached) {
      recommendedAction = 'notifyManager';
    } else if (isTimeoutExceeded || minutesUntilMeeting <= 0) {
      recommendedAction = 'stop';
    } else {
      recommendedAction = 'continue';
    }
  
    return {
      shouldContinue,
      isTimeoutExceeded,
      isMaxAttemptsReached,
      recommendedAction,
      elapsedMinutes,
      minutesUntilMeeting,
    };
  }
  return { determinePromptionLoopEnd };
})();
