/* AIVIC_FUNCTION_BUNDLE_START owner=shouldTerminateCampaign exports=shouldTerminateCampaign */
const __aivicBundle_97_shouldTerminateCampaign = (() => {
  interface ShouldTerminateCampaignInput {
    retryCount: number;
    maxRetryAttempts?: number;
    currentTime?: Date;
    lastCampaignTime?: Date;
    campaignStartTime?: Date;
    maxCampaignDurationMinutes?: number;
    targetResponseCount?: number;
    currentResponseCount?: number;
    campaignDeadline?: Date;
  }
  
  interface ShouldTerminateCampaignOutput {
    shouldTerminate: boolean;
    reason: string;
    elapsedMinutes: number;
    remainingMinutes: number;
  }
  
   function shouldTerminateCampaign(
    input: ShouldTerminateCampaignInput
  ): ShouldTerminateCampaignOutput {
    if (input.retryCount === null || input.retryCount === undefined) {
      throw new Error('催促試行回数が不正です');
    }
  
    const now = input.currentTime ?? new Date();
    const startTime = input.campaignStartTime ?? input.lastCampaignTime ?? now;
    const deadline = input.campaignDeadline ?? new Date(now.getTime() + 60 * 60 * 1000);
    const maxDurationMinutes = input.maxCampaignDurationMinutes ?? 60;
    const maxRetries = input.maxRetryAttempts ?? 3;
    const targetCount = input.targetResponseCount ?? 0;
    const currentCount = input.currentResponseCount ?? 0;
  
    const elapsedMs = now.getTime() - startTime.getTime();
    const elapsedMinutes = Math.floor(elapsedMs / (1000 * 60));
  
    const deadlineMs = deadline.getTime() - startTime.getTime();
    const remainingMinutes = Math.floor(deadlineMs / (1000 * 60)) - elapsedMinutes;
  
    let shouldTerminate = false;
    let reason = '継続中';
  
    if (input.retryCount >= maxRetries) {
      shouldTerminate = true;
      reason = '最大試行回数に到達';
    } else if (targetCount > 0 && currentCount >= targetCount) {
      shouldTerminate = true;
      reason = '目標応答数に到達';
    } else if (elapsedMinutes >= maxDurationMinutes) {
      shouldTerminate = true;
      reason = '最大継続時間を超過';
    } else if (now.getTime() >= deadline.getTime()) {
      shouldTerminate = true;
      reason = 'キャンペーン期限に到達';
    }
  
    return {
      shouldTerminate,
      reason,
      elapsedMinutes,
      remainingMinutes: Math.max(0, remainingMinutes),
    };
  }
  return { shouldTerminateCampaign };
})();
export const shouldTerminateCampaign = __aivicBundle_97_shouldTerminateCampaign.shouldTerminateCampaign;
/* AIVIC_FUNCTION_BUNDLE_END owner=shouldTerminateCampaign */

