/* AIVIC_FUNCTION_BUNDLE_START owner=checkPromptLoopTerminationCondition exports=checkPromptLoopTerminationCondition */
const __aivicBundle_99_checkPromptLoopTerminationCondition = (() => {
  function checkPromptLoopTerminationCondition(loopMetadata: {
    max_prompt_attempts?: number | null;
    current_prompt_count?: number;
    last_response_received_at?: Date | null;
    timeout_minutes?: number;
    startTime?: Date;
    maxAttempts?: number;
    timeoutMinutes?: number;
    currentAttempt?: number;
    responseReceived?: boolean;
    meetingStartTime?: Date;
  }): {
    isTerminationConditionMet: boolean;
    terminationCondition:
      | "timeout"
      | "max_attempts"
      | "response_received"
      | "meeting_approaching"
      | "none";
    minutesRemaining: number;
  } {
    // Validate required field: max_prompt_attempts (or maxAttempts)
    const maxAttempts =
      loopMetadata.max_prompt_attempts ?? loopMetadata.maxAttempts;
    if (maxAttempts === null || maxAttempts === undefined) {
      throw new Error("規定催促回数上限が指定されていません");
    }
  
    // Extract parameters with fallback to camelCase variants
    const currentAttempt =
      loopMetadata.current_prompt_count ?? loopMetadata.currentAttempt ?? 0;
    const lastResponseReceivedAt =
      loopMetadata.last_response_received_at ??
      (loopMetadata.responseReceived ? new Date() : null);
    const timeoutMinutes =
      loopMetadata.timeout_minutes ?? loopMetadata.timeoutMinutes ?? 0;
    const startTime = loopMetadata.startTime ?? new Date();
    const meetingStartTime = loopMetadata.meetingStartTime ?? new Date();
  
    const now = new Date();
  
    // Calculate elapsed time in minutes
    const elapsedMinutes = (now.getTime() - startTime.getTime()) / (1000 * 60);
  
    // Calculate minutes until meeting
    const minutesUntilMeeting =
      (meetingStartTime.getTime() - now.getTime()) / (1000 * 60);
  
    // Check termination conditions in priority order
    // 1. Response received
    if (lastResponseReceivedAt !== null && lastResponseReceivedAt !== undefined) {
      return {
        isTerminationConditionMet: true,
        terminationCondition: "response_received",
        minutesRemaining: Math.ceil(minutesUntilMeeting),
      };
    }
  
    // 2. Max attempts reached
    if (currentAttempt >= maxAttempts) {
      return {
        isTerminationConditionMet: true,
        terminationCondition: "max_attempts",
        minutesRemaining: Math.ceil(minutesUntilMeeting),
      };
    }
  
    // 3. Timeout exceeded
    if (elapsedMinutes >= timeoutMinutes) {
      return {
        isTerminationConditionMet: true,
        terminationCondition: "timeout",
        minutesRemaining: Math.ceil(minutesUntilMeeting),
      };
    }
  
    // 4. Meeting approaching (less than 5 minutes)
    if (minutesUntilMeeting <= 5 && minutesUntilMeeting > 0) {
      return {
        isTerminationConditionMet: true,
        terminationCondition: "meeting_approaching",
        minutesRemaining: Math.ceil(minutesUntilMeeting),
      };
    }
  
    // No termination condition met
    return {
      isTerminationConditionMet: false,
      terminationCondition: "none",
      minutesRemaining: Math.ceil(minutesUntilMeeting),
    };
  }
  return { checkPromptLoopTerminationCondition };
})();
export const checkPromptLoopTerminationCondition = __aivicBundle_99_checkPromptLoopTerminationCondition.checkPromptLoopTerminationCondition;
/* AIVIC_FUNCTION_BUNDLE_END owner=checkPromptLoopTerminationCondition */

/* AIVIC_FUNCTION_BUNDLE_START owner=validateReminderLimit exports=validateReminderLimit */
const __aivicBundle_100_validateReminderLimit = (() => {
  function validateReminderLimit(
    maxReminderAttempts: number,
    currentAttemptCount?: number,
    lastReminderTime?: Date,
    reminderIntervalMinutes?: number,
    reminderId?: string
  ): { isWithinLimit: boolean; nextReminderEligibleTime: Date; attemptsRemaining: number; errorMessage?: string } {
    if (reminderId === undefined || reminderId === null) { throw new Error("reminderId is required"); }
    // Validate maxReminderAttempts is non-negative
    if (maxReminderAttempts < 0) {
      throw new Error('催促回数上限は0以上である必要があります');
    }
  
    const currentAttempts = currentAttemptCount ?? 0;
    const intervalMinutes = reminderIntervalMinutes ?? 0;
    const lastTime = lastReminderTime ?? new Date();
  
    // Calculate next eligible reminder time
    const nextReminderEligibleTime = new Date(lastTime.getTime() + intervalMinutes * 60 * 1000);
  
    // Calculate remaining attempts
    const attemptsRemaining = Math.max(0, maxReminderAttempts - currentAttempts);
  
    // Determine if within limit
    const isWithinLimit = currentAttempts < maxReminderAttempts;
  
    // Build result
    const result: { isWithinLimit: boolean; nextReminderEligibleTime: Date; attemptsRemaining: number; errorMessage?: string } = {
      isWithinLimit,
      nextReminderEligibleTime,
      attemptsRemaining,
    };
  
    // Add error message if at or beyond limit
    if (!isWithinLimit) {
      result.errorMessage = '最大試行回数に到達しました';
    }
  
    return result;
  }
  return { validateReminderLimit };
})();
export const validateReminderLimit = __aivicBundle_100_validateReminderLimit.validateReminderLimit;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateReminderLimit */

