const __aivicBundle_101_validateAndInitializePromptTimeout = (() => {
  function validateAndInitializePromptTimeout(
    promptTimeoutMinutes?: number | null,
    maxPromptAttempts?: number,
    morningMeetingStartTime?: Date
  ): { isValid: boolean; effectiveTimeoutMinutes: number; maxAttempts: number; validationErrors: string[] } {
    const validationErrors: string[] = [];
  
    // null チェック
    if (promptTimeoutMinutes === null || promptTimeoutMinutes === undefined) {
      validationErrors.push("promptTimeoutInterval は null または undefined にできません");
    }
  
    // タイムアウト分数の妥当性チェック
    if (promptTimeoutMinutes !== null && promptTimeoutMinutes !== undefined) {
      if (!Number.isFinite(promptTimeoutMinutes)) {
        validationErrors.push("タイムアウト分数は有限な数値である必要があります");
      } else if (promptTimeoutMinutes < 1) {
        validationErrors.push("タイムアウト分数は1分以上である必要があります");
      }
    }
  
    // 最大試行回数の妥当性チェック
    if (maxPromptAttempts !== null && maxPromptAttempts !== undefined) {
      if (!Number.isFinite(maxPromptAttempts)) {
        validationErrors.push("最大試行回数は有限な数値である必要があります");
      } else if (maxPromptAttempts < 1) {
        validationErrors.push("最大試行回数は1回以上である必要があります");
      }
    }
  
    // 朝会開始時刻の妥当性チェック
    if (morningMeetingStartTime !== null && morningMeetingStartTime !== undefined) {
      if (!(morningMeetingStartTime instanceof Date) || isNaN(morningMeetingStartTime.getTime())) {
        validationErrors.push("朝会開始時刻は有効な Date オブジェクトである必要があります");
      }
    }
  
    const effectiveTimeoutMinutes = promptTimeoutMinutes && Number.isFinite(promptTimeoutMinutes) && promptTimeoutMinutes >= 1 ? promptTimeoutMinutes : 0;
    const effectiveMaxAttempts = maxPromptAttempts && Number.isFinite(maxPromptAttempts) && maxPromptAttempts >= 1 ? maxPromptAttempts : 0;
  
    return {
      isValid: validationErrors.length === 0,
      effectiveTimeoutMinutes,
      maxAttempts: effectiveMaxAttempts,
      validationErrors
    };
  }
  return { validateAndInitializePromptTimeout };
})();
export const validateAndInitializePromptTimeout = __aivicBundle_101_validateAndInitializePromptTimeout.validateAndInitializePromptTimeout;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateAndInitializePromptTimeout */

/* AIVIC_FUNCTION_BUNDLE_START owner=validatePromptRetryTimeout exports=validatePromptRetryTimeout */
const __aivicBundle_102_validatePromptRetryTimeout = (() => {
  function validatePromptRetryTimeout(
    retryTimeoutMinutes: number,
    maxRetries?: number,
    previousAttemptTime?: Date,
    currentTime?: Date
  ): {
    canRetry: boolean;
    nextRetryEligibleTime: Date;
    minutesUntilEligible: number;
    validationErrors: string[];
  } {
    if (maxRetries === undefined || maxRetries === null) { throw new Error("maxRetries is required"); }
    const validationErrors: string[] = [];
  
    // Validate retryTimeoutMinutes
    if (retryTimeoutMinutes < 0) {
      validationErrors.push('催促タイムアウト待機時間は0以上である必要があります');
    }
  
    // If validation errors exist, throw immediately
    if (validationErrors.length > 0) {
      throw new Error(validationErrors[0]);
    }
  
    // Set defaults for optional parameters
    
    const previousAttemptTimeValue = previousAttemptTime ?? new Date();
    const currentTimeValue = currentTime ?? new Date();
  
    // Calculate next retry eligible time
    const nextRetryEligibleTime = new Date(
      previousAttemptTimeValue.getTime() + retryTimeoutMinutes * 60 * 1000
    );
  
    // Calculate minutes until eligible
    const elapsedMs = currentTimeValue.getTime() - previousAttemptTimeValue.getTime();
    const elapsedMinutes = elapsedMs / (60 * 1000);
    const minutesUntilEligible = Math.max(0, retryTimeoutMinutes - elapsedMinutes);
  
    // Determine if retry is allowed
    const canRetry = elapsedMinutes >= retryTimeoutMinutes;
  
    return {
      canRetry,
      nextRetryEligibleTime,
      minutesUntilEligible,
      validationErrors,
    };
  }
  return { validatePromptRetryTimeout };
})();
export const validatePromptRetryTimeout = __aivicBundle_102_validatePromptRetryTimeout.validatePromptRetryTimeout;
