/* AIVIC_FUNCTION_BUNDLE_START owner=notifyUnsubmittedMembers exports=notifyUnsubmittedMembers */
const __aivicBundle_106_notifyUnsubmittedMembers = (() => {
  function notifyUnsubmittedMembers(
    input: any,
    unsubmittedMembers?: any,
    sendEmailFn?: any
  ): { notificationSent: boolean; recipientCount: number; status: string } {
    // Determine input structure: either (unsubmittedList) or (config, unsubmittedList, sendEmailFn)
    let members: Array<{ user_id: string; user_name: string }>;
    let managerEmail: string | null | undefined;
    let sendEmail: ((email: string, subject: string, body: string) => void) | undefined;
  
    if (Array.isArray(input)) {
      // First signature: notifyUnsubmittedMembers(unsubmittedList)
      members = input;
      managerEmail = undefined;
      sendEmail = undefined;
    } else if (typeof input === 'object' && input !== null) {
      // Second signature: notifyUnsubmittedMembers(config, unsubmittedList, sendEmailFn)
      members = Array.isArray(unsubmittedMembers) ? unsubmittedMembers : [];
      managerEmail = input.department_head_email;
      sendEmail = typeof sendEmailFn === 'function' ? sendEmailFn : undefined;
    } else {
      members = [];
      managerEmail = undefined;
      sendEmail = undefined;
    }
  
    // Validation: empty unsubmitted members list
    if (!members || members.length === 0) {
      throw new Error('未提出部員情報が必要です');
    }
  
    // Validation: manager email must be provided and not null
    if (managerEmail === null || managerEmail === undefined) {
      throw new Error('部長のメールアドレスが必要です');
    }
  
    // Build notification content
    const memberNames = members.map((m) => m.user_name).join(', ');
    const subject = '朝会報告未提出のお知らせ';
    const body = `以下の部員から朝会報告がまだ提出されていません:\n${memberNames}`;
  
    // Send notification if sendEmail function is provided
    if (sendEmail && typeof sendEmail === 'function') {
      sendEmail(managerEmail, subject, body);
    }
  
    return {
      notificationSent: true,
      recipientCount: members.length,
      status: '送信完了',
    };
  }
  return { notifyUnsubmittedMembers };
})();
