/* AIVIC_FUNCTION_BUNDLE_START owner=stopPromptionLoopWhenThresholdReached exports=stopPromptionLoopWhenThresholdReached */
const __aivicBundle_115_stopPromptionLoopWhenThresholdReached = (() => {
  function stopPromptionLoopWhenThresholdReached(input: any): any {
    const { loop_start_time, current_time, unprompted_user_id, dept_head_id, threshold_minutes, promptStartTime, maxPromptAttempts, promptTimeoutMinutes, currentPromptAttemptCount, reportReceivedTime, morningMeetingStartTime } = input;
  
    // Handle snake_case test input
    if (loop_start_time !== undefined && current_time !== undefined) {
      const elapsedMs = current_time.getTime() - loop_start_time.getTime();
      const elapsedMinutes = Math.floor(elapsedMs / (60 * 1000));
      
      
  
      return {
        loop_start_time,
        current_time,
        unprompted_user_id,
        dept_head_id,
        threshold_minutes,
        send_mail_called: false,
        is_active: false,
      };
    }
  
    // Handle camelCase plan input
    if (promptStartTime !== undefined && morningMeetingStartTime !== undefined) {
      const now = new Date();
      const elapsedMs = now.getTime() - promptStartTime.getTime();
      const elapsedMinutes = Math.floor(elapsedMs / (60 * 1000));
  
      const timeoutMs = promptTimeoutMinutes * 60 * 1000;
      const isTimeoutExceeded = elapsedMs >= timeoutMs;
      const isMaxAttemptsReached = currentPromptAttemptCount >= maxPromptAttempts;
  
      const minutesUntilMeeting = Math.floor(
        (morningMeetingStartTime.getTime() - now.getTime()) / (60 * 1000)
      );
      const is30MinutesBeforeMeeting = minutesUntilMeeting <= 30;
  
      const reportHasArrived = reportReceivedTime !== null;
  
      let shouldTerminate = false;
      let recommendedAction: 'continue' | 'stop' | 'notifyManager' = 'continue';
  
      if (reportHasArrived) {
        shouldTerminate = true;
        recommendedAction = 'stop';
      } else if (isTimeoutExceeded || isMaxAttemptsReached || is30MinutesBeforeMeeting) {
        shouldTerminate = true;
        recommendedAction = 'notifyManager';
      }
  
      return {
        shouldContinuePrompting: !shouldTerminate,
        isTimeoutExceeded,
        isMaxAttemptsReached,
        recommendedAction,
        elapsedMinutes,
        minutesUntilMeeting,
      } as PromptLoopTerminationResult;
    }
  
    return {
      shouldContinuePrompting: true,
      isTimeoutExceeded: false,
      isMaxAttemptsReached: false,
      recommendedAction: 'continue',
      elapsedMinutes: 0,
      minutesUntilMeeting: 0,
    } as PromptLoopTerminationResult;
  }
  return { stopPromptionLoopWhenThresholdReached };
})();
export const stopPromptionLoopWhenThresholdReached = __aivicBundle_115_stopPromptionLoopWhenThresholdReached.stopPromptionLoopWhenThresholdReached;
/* AIVIC_FUNCTION_BUNDLE_END owner=stopPromptionLoopWhenThresholdReached */

