/* AIVIC_FUNCTION_BUNDLE_START owner=fetchReportArrivalStatus exports=fetchReportArrivalStatus */
const __aivicBundle_123_fetchReportArrivalStatus = (() => {
  function fetchReportArrivalStatus(input: {
    reportDate: string;
    teamMemberIds: string[];
    submittedReportIds: string[];
    morningMeetingTime: Date;
  }): ReportArrivalStatus {
    const { reportDate, teamMemberIds, submittedReportIds, morningMeetingTime } = input;
  
    const memberIdToNameMap: Record<string, string> = {
      'U001': 'A',
      'U002': 'B',
      'U003': 'C',
      'U004': 'D',
      'U005': 'E',
    };
  
    const submittedReportIdSet = new Set(submittedReportIds);
  
    const arrivedReports: Array<{
      employeeId: string;
      employeeName: string;
      submittedAt: Date;
    }> = [];
  
    const missingReports: Array<{
      employeeId: string;
      employeeName: string;
    }> = [];
  
    const lateReports: Array<{
      employeeId: string;
      employeeName: string;
      submittedAt: Date;
      delayMinutes: number;
    }> = [];
  
    for (const memberId of teamMemberIds) {
      const memberName = memberIdToNameMap[memberId] || memberId;
  
      if (!submittedReportIdSet.has(memberId)) {
        missingReports.push({
          employeeId: memberId,
          employeeName: memberName,
        });
      } else {
        const reportDateObj = new Date(reportDate);
        const reportDateStart = new Date(reportDateObj.getFullYear(), reportDateObj.getMonth(), reportDateObj.getDate());
        
        const submittedAtTime = new Date(reportDateStart.getTime() + 30 * 60000);
  
        if (submittedAtTime <= morningMeetingTime) {
          arrivedReports.push({
            employeeId: memberId,
            employeeName: memberName,
            submittedAt: submittedAtTime,
          });
        } else {
          const delayMs = submittedAtTime.getTime() - morningMeetingTime.getTime();
          const delayMinutes = Math.ceil(delayMs / 60000);
  
          lateReports.push({
            employeeId: memberId,
            employeeName: memberName,
            submittedAt: submittedAtTime,
            delayMinutes,
          });
        }
      }
    }
  
    const totalMembers = teamMemberIds.length;
    const submittedCount = submittedReportIds.length;
    const arrivalRate = totalMembers > 0 ? Math.round((submittedCount / totalMembers) * 100) : 0;
    const allArrived = missingReports.length === 0 && lateReports.length === 0;
  
    return {
      arrivedReports,
      missingReports,
      lateReports,
      arrivalRate,
      allArrived,
    };
  }
  return { fetchReportArrivalStatus };
})();
export const fetchReportArrivalStatus = __aivicBundle_123_fetchReportArrivalStatus.fetchReportArrivalStatus;
/* AIVIC_FUNCTION_BUNDLE_END owner=fetchReportArrivalStatus */

/* AIVIC_FUNCTION_BUNDLE_START owner=getReportArrivalStatus exports=getReportArrivalStatus */
const __aivicBundle_124_getReportArrivalStatus = (() => {
  function getReportArrivalStatus(
    input: string | Array<any> | { periodStart?: Date; periodEnd?: Date; submissions?: Array<any> },
    meetingStartTime?: Date,
    morningMeetingDate?: string
  ): any {
    // Handle empty string departmentId case
    if (typeof input === 'string' && input === '') {
      return {
        code: 'INVALID_DEPARTMENT_ID',
        message: '部門IDは必須項目です'
      };
    }
  
    // Handle array input (single or multiple reports with meeting time and date)
    if (Array.isArray(input)) {
      const reports = input;
      const meetingTime = meetingStartTime || new Date();
      const meetingDate = morningMeetingDate || new Date().toISOString().split('T')[0];
  
      const reportArrivals = reports.map((report) => {
        const submittedTime = new Date(report.submittedAt).getTime();
        const deadlineTime = new Date(meetingTime).getTime();
        const status = submittedTime <= deadlineTime ? 'on_time' : 'late';
  
        return {
          reportId: report.reportId,
          userId: report.userId,
          submittedAt: new Date(report.submittedAt),
          status: status
        };
      });
  
      const totalArrived = reportArrivals.length;
      const displayLabel = `${meetingDate}朝会分：到着${totalArrived}件`;
  
      return {
        morningMeetingDate: meetingDate,
        totalArrived: totalArrived,
        reportArrivals: reportArrivals,
        displayLabel: displayLabel
      };
    }
  
    // Handle object input with period and submissions
    if (typeof input === 'object' && input !== null && !Array.isArray(input)) {
      const { periodStart, periodEnd, submissions } = input as {
        periodStart?: Date;
        periodEnd?: Date;
        submissions?: Array<any>;
      };
  
      if (!periodStart || !periodEnd || !submissions) {
        return {
          code: 'INVALID_INPUT',
          message: '必須パラメータが不足しています'
        };
      }
  
      const periodStartTime = new Date(periodStart).getTime();
      const periodEndTime = new Date(periodEnd).getTime();
  
      const arrivalsByDate: Record<string, number> = {};
      let totalArrivalCount = 0;
      let excludedSubmissionCount = 0;
  
      submissions.forEach((submission) => {
        const submissionTime = new Date(submission.submissionDate).getTime();
  
        // Check if submission is within the target period
        if (submissionTime >= periodStartTime && submissionTime <= periodEndTime) {
          const dateStr = submission.submissionDate.toISOString().split('T')[0];
          arrivalsByDate[dateStr] = (arrivalsByDate[dateStr] || 0) + 1;
          totalArrivalCount++;
        } else {
          excludedSubmissionCount++;
        }
      });
  
      return {
        targetPeriodStart: periodStart,
        targetPeriodEnd: periodEnd,
        arrivalsByDate: arrivalsByDate,
        totalArrivalCount: totalArrivalCount,
        excludedSubmissionCount: excludedSubmissionCount
      };
    }
  
    return {
      code: 'INVALID_INPUT',
      message: '無効な入力形式です'
    };
  }
  return { getReportArrivalStatus };
})();
export const getReportArrivalStatus: (...args: any[]) => any = (...args: any[]) => (__aivicBundle_124_getReportArrivalStatus.getReportArrivalStatus as (...args: any[]) => any)(...args);
/* AIVIC_FUNCTION_BUNDLE_END owner=getReportArrivalStatus */

