/* AIVIC_FUNCTION_BUNDLE_START owner=verifyReportArrivalStatus exports=verifyReportArrivalStatus */
const __aivicBundle_127_verifyReportArrivalStatus = (() => {
  interface VerifyReportArrivalStatusErrorResult {
    error: true;
    errorCode: string;
    errorMessage: string;
  }
  
  interface VerifyReportArrivalStatusForbiddenResult {
    [key: string]: any;
  }
  
  interface VerifyReportArrivalStatusSuccessResult extends ReportArrivalStatus {}
  
  type VerifyReportArrivalStatusResult =
    | VerifyReportArrivalStatusErrorResult
    | VerifyReportArrivalStatusForbiddenResult
    | VerifyReportArrivalStatusSuccessResult;
  
   function verifyReportArrivalStatus(
    input: any
  ): VerifyReportArrivalStatusResult {
    // Check for permission-based access control
    if (
      input.user_id !== undefined &&
      input.user_role !== undefined &&
      input.department_id !== undefined &&
      input.timestamp !== undefined
    ) {
      // Non-manager role check
      if (input.user_role !== "manager" && input.user_role !== "admin") {
        return {
          success: false,
          status_code: 403,
          error_message: "このページへのアクセス権限がありません",
        };
      }
    }
  
    // Check for missing expectedCount
    if (input.expectedCount === null || input.expectedCount === undefined) {
      return {
        error: true,
        errorCode: "MISSING_EXPECTED_COUNT",
        errorMessage: "期待報告人数が指定されていません",
      };
    }
  
    // Standard report arrival status verification
    const expectedEmployeeIds: string[] = input.expectedEmployeeIds || [];
    const reportSubmissions: Array<{
      employeeId: string;
      employeeName: string;
      submittedAt: Date;
    }> = input.reportSubmissions || [];
    const reportDeadlineTime: Date = input.reportDeadlineTime || new Date();
  
    const submittedEmployeeIds = new Set(
      reportSubmissions.map((r) => r.employeeId)
    );
  
    const arrivedReports: Array<{
      employeeId: string;
      employeeName: string;
      submittedAt: Date;
    }> = [];
    const lateReports: Array<{
      employeeId: string;
      employeeName: string;
      submittedAt: Date;
      delayMinutes: number;
    }> = [];
  
    for (const submission of reportSubmissions) {
      const delayMs =
        submission.submittedAt.getTime() - reportDeadlineTime.getTime();
      const delayMinutes = Math.floor(delayMs / (1000 * 60));
  
      if (delayMinutes <= 0) {
        arrivedReports.push({
          employeeId: submission.employeeId,
          employeeName: submission.employeeName,
          submittedAt: submission.submittedAt,
        });
      } else {
        lateReports.push({
          employeeId: submission.employeeId,
          employeeName: submission.employeeName,
          submittedAt: submission.submittedAt,
          delayMinutes,
        });
      }
    }
  
    const missingReports: Array<{
      employeeId: string;
      employeeName: string;
    }> = [];
  
    for (const employeeId of expectedEmployeeIds) {
      if (!submittedEmployeeIds.has(employeeId)) {
        missingReports.push({
          employeeId,
          employeeName: "",
        });
      }
    }
  
    const totalExpected = expectedEmployeeIds.length || 1;
    const totalSubmitted = arrivedReports.length + lateReports.length;
    const arrivalRate = Math.round((totalSubmitted / totalExpected) * 100);
    const allArrived =
      missingReports.length === 0 && lateReports.length === 0;
  
    return {
      arrivedReports,
      missingReports,
      lateReports,
      arrivalRate,
      allArrived,
    };
  }
  return { verifyReportArrivalStatus };
})();
