/* AIVIC_FUNCTION_BUNDLE_START owner=getArrivalStatusSummary exports=getArrivalStatusSummary */
const __aivicBundle_135_getArrivalStatusSummary = (() => {
  function getArrivalStatusSummary(
    input: ReportSubmissionEvent[] | { arrivalStatus: ReportArrivalStatus; reportDate: string }
  ): ReportArrivalStatus & {
    summaryText: string;
    totalExpected: number;
    totalArrived: number;
    totalMissing: number;
    arrivalPercentage: number;
    allArrivedFlag: boolean;
    displayMessage: string;
    sortedReports?: Array<{
      reportId: string;
      employeeId: string;
      submissionTimestamp: Date;
    }>;
    isChronologicallyOrdered?: boolean;
    totalReportsReceived?: number;
  } {
    let arrivalStatus: ReportArrivalStatus;
    let reportDate: string;
  
    // Handle both input formats: array of ReportSubmissionEvent or object with arrivalStatus
    if (Array.isArray(input)) {
      // Input is array of ReportSubmissionEvent
      const events = input as Array<ReportSubmissionEvent & { employeeId?: string }>;
  
      // Sort by submission timestamp
      const sortedReports = [...events].sort(
        (a, b) =>
          new Date(a.submissionTimestamp).getTime() -
          new Date(b.submissionTimestamp).getTime()
      );
  
      const totalReportsReceived = events.length;
      const totalExpected = events.length;
      const totalArrived = events.length;
      const totalMissing = 0;
      const arrivalPercentage = totalExpected > 0 ? 100 : 0;
      const allArrivedFlag = true;
  
      return {
        arrivedReports: events.map((e) => ({
          employeeId: e.employeeId || e.userId || "",
          employeeName: e.userName || "",
          submittedAt: new Date(e.submissionTimestamp),
        })),
        missingReports: [],
        lateReports: [],
        arrivalRate: 100,
        allArrived: true,
        summaryText: `${totalExpected}名中${totalArrived}名から報告を受け取りました。未送信：${totalMissing}名`,
        totalExpected,
        totalArrived,
        totalMissing,
        arrivalPercentage,
        allArrivedFlag,
        displayMessage: "全員送信完了",
        sortedReports: sortedReports.map((e) => ({
          reportId: e.reportId,
          employeeId: e.employeeId || e.userId || "",
          submissionTimestamp: new Date(e.submissionTimestamp),
        })),
        isChronologicallyOrdered: true,
        totalReportsReceived,
      };
    } else {
      // Input is object with arrivalStatus and reportDate
      const payload = input as { arrivalStatus: ReportArrivalStatus; reportDate: string };
      arrivalStatus = payload.arrivalStatus;
      reportDate = payload.reportDate;
  
      const totalExpected =
        (arrivalStatus.arrivedReports?.length || 0) +
        (arrivalStatus.missingReports?.length || 0) +
        (arrivalStatus.lateReports?.length || 0);
  
      const totalArrived = arrivalStatus.arrivedReports?.length || 0;
      const totalMissing = arrivalStatus.missingReports?.length || 0;
      const totalLate = arrivalStatus.lateReports?.length || 0;
  
      const arrivalPercentage =
        totalExpected > 0 ? Math.round((totalArrived / totalExpected) * 100) : 0;
  
      const allArrivedFlag = arrivalStatus.allArrived === true;
  
      let displayMessage = "";
      if (allArrivedFlag) {
        displayMessage = "全員送信完了";
      } else if (totalMissing > 0) {
        displayMessage = `${totalMissing}名未送信`;
      } else if (totalLate > 0) {
        displayMessage = `${totalLate}名遅延`;
      } else {
        displayMessage = "確認中";
      }
  
      const summaryText = `${totalExpected}名中${totalArrived}名から報告を受け取りました。未送信：${totalMissing}名`;
  
      return {
        ...arrivalStatus,
        summaryText,
        totalExpected,
        totalArrived,
        totalMissing,
        arrivalPercentage,
        allArrivedFlag,
        displayMessage,
      };
    }
  }
  return { getArrivalStatusSummary };
})();
