/* AIVIC_FUNCTION_BUNDLE_START owner=validateReportContent exports=validateReportContent */
const __aivicBundle_141_validateReportContent = (() => {
  function validateReportContent(content: {
    yesterday_accomplishment?: string;
    today_plan?: string;
    current_issues?: string;
    yesterday?: string;
    today?: string;
    issues?: string;
  }): {
    status: string;
    message: string;
    isValid?: boolean;
    missingFields?: string[];
  } {
    // Handle both snake_case and camelCase property names
    const yesterday =
      content.yesterday_accomplishment ?? content.yesterday ?? "";
    const today = content.today_plan ?? content.today ?? "";
    const issues = content.current_issues ?? content.issues ?? "";
  
    // Check if all three fields are empty
    const allEmpty =
      yesterday.trim() === "" &&
      today.trim() === "" &&
      issues.trim() === "";
  
    if (allEmpty) {
      return {
        status: "warning",
        message:
          "昨日やったこと、今日やること、抱えている課題のいずれか1つ以上の入力が必須です",
        isValid: false,
        missingFields: ["昨日の実績", "今日の予定", "抱えている課題"],
      };
    }
  
    // Collect missing fields (for camelCase compatibility)
    const missingFields: string[] = [];
    if (yesterday.trim() === "") {
      missingFields.push("昨日の実績");
    }
    if (today.trim() === "") {
      missingFields.push("今日の予定");
    }
    if (issues.trim() === "") {
      missingFields.push("抱えている課題");
    }
  
    return {
      status: missingFields.length > 0 ? "warning" : "success",
      message:
        missingFields.length > 0
          ? `以下の項目が未入力です: ${missingFields.join(", ")}`
          : "すべての項目が入力されています",
      isValid: missingFields.length === 0,
      missingFields,
    };
  }
  return { validateReportContent };
})();
