/* AIVIC_FUNCTION_BUNDLE_START owner=sendReminderEmailToUnreportedMembers exports=sendReminderEmailToUnreportedMembers */
const __aivicBundle_143_sendReminderEmailToUnreportedMembers = (() => {
  function sendReminderEmailToUnreportedMembers(
    managerEmail: string,
    unreportedMembers: Array<{
      user_id: string;
      user_name: string;
      department_id?: string;
    }>,
    morningMeetingTime: Date
  ): { remindersSent: number; status: string } {
    if (!managerEmail || managerEmail.trim() === '') {
      throw new Error('メールアドレスが不正です');
    }
  
    if (!Array.isArray(unreportedMembers)) {
      return { remindersSent: 0, status: '失敗' };
    }
  
    if (unreportedMembers.length === 0) {
      return { remindersSent: 0, status: '対象者なし' };
    }
  
    const validMembers = unreportedMembers.filter(
      (member) => member && member.user_id && member.user_name
    );
  
    if (validMembers.length === 0) {
      return { remindersSent: 0, status: '失敗' };
    }
  
    const currentTime = new Date();
    const timeUntilMeeting = morningMeetingTime.getTime() - currentTime.getTime();
    const minutesUntilMeeting = Math.floor(timeUntilMeeting / (1000 * 60));
  
    const remindersSent = validMembers.length;
  
    let status = '送信完了';
    if (minutesUntilMeeting <= 0) {
      status = '期限超過';
    } else if (minutesUntilMeeting < 15) {
      status = '緊急送信';
    }
  
    return {
      remindersSent,
      status,
    };
  }
  return { sendReminderEmailToUnreportedMembers };
})();
export const sendReminderEmailToUnreportedMembers = __aivicBundle_143_sendReminderEmailToUnreportedMembers.sendReminderEmailToUnreportedMembers;
/* AIVIC_FUNCTION_BUNDLE_END owner=sendReminderEmailToUnreportedMembers */

