const __aivicBundle_146_sendUnsumittedReportReminderNotification = (() => {
  async function sendUnsumittedReportReminderNotification(
    input: any
  ): Promise<any> {
    const notificationTimestamp = new Date();
  
    // Extract input fields - support both snake_case and camelCase
    const employees = input.employees || [];
    const submissionHistory = input.submission_history || input.submissionHistory || [];
    
    
  
    // Determine which employees have NOT submitted reports
    const submittedUserIds = new Set(
      submissionHistory.map((record: any) => record.user_id || record.userId)
    );
  
    const unsubmittedEmployees = employees.filter(
      (emp: any) => !submittedUserIds.has(emp.user_id)
    );
  
    const unsumittedUserIds = unsubmittedEmployees.map((emp: any) => emp.user_id);
    const totalUnsumittedCount = unsubmittedEmployees.length;
  
    // Send reminder emails to each unsubmitted employee
    const mailSendResults: any[] = [];
    let reminderMailsSent = 0;
  
    for (const employee of unsubmittedEmployees) {
      try {
        const mailBody = `朝会報告がまだ送信されていません。\n\n従業員ID: ${employee.user_id}\n従業員名: ${employee.user_name}\n\nお早めにご提出ください。`;
  
        // Simulate mail send API call
        const mailResponse = await fetch("/api/send-mail", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            recipient_email: employee.email_address,
            subject: "朝会報告の提出をお願いします",
            body: mailBody,
          }),
        });
  
        if (mailResponse.ok) {
          const mailData = await mailResponse.json();
          mailSendResults.push({
            recipient_email: employee.email_address,
            status: "sent",
            mail_body: mailBody,
            mail_send_id: mailData.mail_send_id,
            sent_at: mailData.sent_at,
          });
          reminderMailsSent++;
        } else {
          mailSendResults.push({
            recipient_email: employee.email_address,
            status: "failed",
            mail_body: mailBody,
          });
        }
      } catch (error) {
        mailSendResults.push({
          recipient_email: employee.email_address,
          status: "failed",
          mail_body: "",
        });
      }
    }
  
    // Determine reminder status
    let reminderStatus = "送信完了";
    if (reminderMailsSent < totalUnsumittedCount) {
      reminderStatus = "部分送信";
    }
    if (reminderMailsSent === 0 && totalUnsumittedCount > 0) {
      reminderStatus = "送信失敗";
    }
    if (totalUnsumittedCount === 0) {
      reminderStatus = "対象者なし";
    }
  
    return {
      notificationSent: reminderMailsSent > 0,
      notificationTimestamp,
      unreportedCount: totalUnsumittedCount,
      reminderStatus,
      total_unsumitted_count: totalUnsumittedCount,
      reminder_mails_sent: reminderMailsSent,
      unsumitted_user_ids: unsumittedUserIds,
      mail_send_results: mailSendResults,
    };
  }
  return { sendUnsumittedReportReminderNotification };
})();
