const __aivicBundle_161_sendReminderEmail = (() => {
  function sendReminderEmail(payload: ReminderEmailPayload): ReminderEmailResult {
    if (payload["managerName"] === undefined || payload["managerName"] === null) { throw new Error("managerName is required"); }
    if (payload["sentAt"] === undefined || payload["sentAt"] === null) { throw new Error("sentAt is required"); }
    const transactionId = `TXN-${randomUUID()}`;
    const sentAt = new Date();
  
    // Validate recipient email
    if (!payload.recipientEmail || payload.recipientEmail.trim() === "") {
      return {
        success: false,
        emailSent: false,
        sentAt,
        recipientEmail: payload.recipientEmail || "",
        unreportedMemberCount: payload.unreportedCount,
        errorMessage: "メールアドレスが不正です",
        transactionId,
      };
    }
  
    // Validate email format (basic check)
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(payload.recipientEmail)) {
      return {
        success: false,
        emailSent: false,
        sentAt,
        recipientEmail: payload.recipientEmail,
        unreportedMemberCount: payload.unreportedCount,
        errorMessage: "メールアドレスが不正です",
        transactionId,
      };
    }
  
    // Validate unreported members list
    if (!payload.unreportedMemberNames || payload.unreportedMemberNames.length === 0) {
      return {
        success: false,
        emailSent: false,
        sentAt,
        recipientEmail: payload.recipientEmail,
        unreportedMemberCount: payload.unreportedCount,
        errorMessage: "未報告部員が指定されていません",
        transactionId,
      };
    }
  
    // Validate deadline and meeting times
    if (!payload.reportDeadlineTime || !payload.morningMeetingTime) {
      return {
        success: false,
        emailSent: false,
        sentAt,
        recipientEmail: payload.recipientEmail,
        unreportedMemberCount: payload.unreportedCount,
        errorMessage: "報告期限または朝礼時刻が指定されていません",
        transactionId,
      };
    }
  
    // Validate required manager information
    if (!payload.managerName || String(payload.managerName).trim() === "") {
      return {
        success: false,
        emailSent: false,
        sentAt,
        recipientEmail: payload.recipientEmail,
        unreportedMemberCount: payload.unreportedCount,
        errorMessage: "部長名が指定されていません",
        transactionId,
      };
    }
  
    if (!payload.sentAt) {
      return {
        success: false,
        emailSent: false,
        sentAt,
        recipientEmail: payload.recipientEmail,
        unreportedMemberCount: payload.unreportedCount,
        errorMessage: "送信時刻が指定されていません",
        transactionId,
      };
    }
  
    // Build email content with deadline and meeting time information
    const deadlineTimeStr = payload.reportDeadlineTime.toLocaleString("ja-JP");
    const meetingTimeStr = payload.morningMeetingTime.toLocaleString("ja-JP");
    const memberList = payload.unreportedMemberNames.join("、");
  
    const emailSubject = `【催促】朝会報告の未提出について（${payload.departmentName}）`;
    const emailBody = `${payload.recipientName}様\n\n以下の部員から朝会報告がまだ提出されていません。\n\n未報告部員: ${memberList}\n報告期限: ${deadlineTimeStr}\n朝礼時刻: ${meetingTimeStr}\n\nお手数ですが、ご確認ください。`;
  
    // Simulate email sending with manager name and sent timestamp validation
    // The email content incorporates deadline/meeting times and manager information
    const emailSendSuccess = emailSubject.length > 0 && emailBody.length > 0 && payload.managerName.length > 0;
  
    if (!emailSendSuccess) {
      return {
        success: false,
        emailSent: false,
        sentAt,
        recipientEmail: payload.recipientEmail,
        unreportedMemberCount: payload.unreportedCount,
        errorMessage: "メール送信サービスが利用できません",
        transactionId,
      };
    }
  
    return {
      success: true,
      emailSent: true,
      sentAt,
      recipientEmail: payload.recipientEmail,
      unreportedMemberCount: payload.unreportedCount,
      transactionId,
    };
  }
  return { sendReminderEmail };
})();
